<div class="wrap breadcrumbs"><a href="<?= e(link_url('/trabalhos')) ?>">Trabalhos</a><span>/</span><span><?= e($item['client']) ?></span></div><?php page_intro($item['client'],e($item['title']),$item['intro']); ?><div class="wrap case-hero-media"><?php image_tag($item['hero'],'Trabalho da Aleixo para '.$item['client'],'',true); ?></div><section class="section"><div class="wrap case-story"><aside><p class="eyebrow">Cliente</p><h2><?= e($item['client']) ?></h2><p><?= e($item['category']) ?></p><?php if(!empty($item['channels'])): ?><p class="eyebrow">Canais</p><p><?= e(implode(' · ',$item['channels'])) ?></p><?php endif; ?></aside><div><?php foreach(['context'=>'Contexto','challenge'=>'Desafio','strategy'=>'Estratégia','idea'=>'Ideia','execution'=>'Execução','media'=>'Mídia','digital'=>'Digital','performance'=>'Performance','results'=>'Resultados'] as $key=>$label): if(empty($item[$key]))continue; ?><section class="story-block reveal"><p class="eyebrow"><?= $label ?></p><p><?= e($item[$key]) ?></p></section><?php endforeach; ?></div></div></section><section class="section"><div class="wrap"><p class="eyebrow">Galeria</p><div class="case-gallery"><?php foreach($item['gallery']??[] as $src): ?><a href="<?= e(asset(str_replace('/assets/','',$src))) ?>" target="_blank" rel="noopener" aria-label="Ampliar peça de <?= e($item['client']) ?>"><?php image_tag($src,'Peça de comunicação para '.$item['client']); ?></a><?php endforeach; ?></div><?php if(!empty($item['video'])): ?><video controls preload="metadata" src="<?= e($item['video']) ?>"></video><?php endif; ?><a class="text-link" href="<?= e(link_url('/trabalhos')) ?>">← Voltar aos trabalhos</a></div></section>